import { afterEach, beforeEach, describe, expect, it, vi } from "vitest"
import type { WizardState } from "../state.js"

// Hoisted mocks so they are installed before the module under test is loaded.
const validateApiKeyMock = vi.hoisted(() => vi.fn())
const authenticateViaBrowserMock = vi.hoisted(() => vi.fn())
const writeApiKeyMock = vi.hoisted(() => vi.fn())
const readApiKeyFromConfigFileMock = vi.hoisted(() => vi.fn())
const passwordMock = vi.hoisted(() => vi.fn())
const confirmMock = vi.hoisted(() => vi.fn())

vi.mock("../../auth/validator.js", () => ({ validateApiKey: validateApiKeyMock }))
vi.mock("../../cli-auth/index.js", () => ({ authenticateViaBrowser: authenticateViaBrowserMock }))
vi.mock("../../config.js", () => ({
	readApiKeyFromConfigFile: readApiKeyFromConfigFileMock,
	writeApiKey: writeApiKeyMock,
}))
vi.mock("../prompt.js", () => ({
	password: passwordMock,
	confirm: confirmMock,
}))

const { runAuthStep } = await import("./auth.js")

describe("runAuthStep", () => {
	let state: WizardState
	let savedApiKey: string | undefined

	beforeEach(() => {
		state = {
			apiKey: "",
			mode: "override",
			scope: "global",
			selectedTools: [],
			telemetryEnabled: false,
			back: false,
			cancelled: false,
		}
		savedApiKey = process.env.KIMCHI_API_KEY
		process.env.KIMCHI_API_KEY = ""
		validateApiKeyMock.mockReset()
		authenticateViaBrowserMock.mockReset()
		writeApiKeyMock.mockReset()
		readApiKeyFromConfigFileMock.mockReset()
		passwordMock.mockReset()
		confirmMock.mockReset()
		vi.spyOn(console, "log").mockImplementation(() => {})
	})

	afterEach(() => {
		vi.restoreAllMocks()
		if (savedApiKey !== undefined) process.env.KIMCHI_API_KEY = savedApiKey
		// biome-ignore lint/performance/noDelete: env var must be deleted, not set to "undefined"
		else delete process.env.KIMCHI_API_KEY
	})

	it("validates and saves a pasted API key", async () => {
		readApiKeyFromConfigFileMock.mockReturnValue(undefined)
		passwordMock.mockResolvedValue({ kind: "next", value: "paste-key-123" })
		validateApiKeyMock.mockResolvedValue({ valid: true })

		await runAuthStep(state, { backable: false })

		expect(validateApiKeyMock).toHaveBeenCalledWith("paste-key-123")
		expect(state.apiKey).toBe("paste-key-123")
		expect(writeApiKeyMock).toHaveBeenCalledWith("paste-key-123")
	})

	it("triggers browser auth when the user presses Enter (empty input)", async () => {
		readApiKeyFromConfigFileMock.mockReturnValue(undefined)
		passwordMock.mockResolvedValue({ kind: "next", value: "" })
		authenticateViaBrowserMock.mockResolvedValue({ token: "browser-token-456" })
		validateApiKeyMock.mockResolvedValue({ valid: true })

		await runAuthStep(state, { backable: false })

		expect(authenticateViaBrowserMock).toHaveBeenCalledTimes(1)
		expect(validateApiKeyMock).toHaveBeenCalledTimes(0)
		expect(state.apiKey).toBe("browser-token-456")
		expect(writeApiKeyMock).toHaveBeenCalledWith("browser-token-456")
	})

	it("retries when browser auth fails and then asks for manual input", async () => {
		readApiKeyFromConfigFileMock.mockReturnValue(undefined)
		passwordMock
			.mockResolvedValueOnce({ kind: "next", value: "" })
			.mockResolvedValueOnce({ kind: "next", value: "fallback-key-789" })
		authenticateViaBrowserMock.mockRejectedValue(new Error("Browser refused"))
		validateApiKeyMock.mockResolvedValue({ valid: true })

		await runAuthStep(state, { backable: false })

		expect(authenticateViaBrowserMock).toHaveBeenCalledTimes(1)
		// After browser failure it loops back and prompts again
		expect(passwordMock).toHaveBeenCalledTimes(2)
		expect(validateApiKeyMock).toHaveBeenCalledWith("fallback-key-789")
		expect(state.apiKey).toBe("fallback-key-789")
	})

	it("uses the saved key without prompting when one exists and user confirms", async () => {
		readApiKeyFromConfigFileMock.mockReturnValue("saved-key")
		confirmMock.mockResolvedValue({ kind: "next", value: true })
		validateApiKeyMock.mockResolvedValue({ valid: true })

		await runAuthStep(state, { backable: true })

		expect(confirmMock).toHaveBeenCalledTimes(1)
		expect(validateApiKeyMock).toHaveBeenCalledWith("saved-key")
		expect(passwordMock).not.toHaveBeenCalled()
		expect(state.apiKey).toBe("saved-key")
	})

	it("prompts for a new key when the saved key is rejected and user opts to replace", async () => {
		readApiKeyFromConfigFileMock.mockReturnValue("saved-key")
		confirmMock.mockResolvedValue({ kind: "next", value: false }) // user says "don't keep it"
		passwordMock.mockResolvedValue({ kind: "next", value: "new-key-abc" })
		validateApiKeyMock.mockResolvedValue({ valid: true })

		await runAuthStep(state, { backable: true })

		expect(confirmMock).toHaveBeenCalledTimes(1)
		expect(passwordMock).toHaveBeenCalledTimes(1)
		expect(validateApiKeyMock).toHaveBeenCalledWith("new-key-abc")
		expect(state.apiKey).toBe("new-key-abc")
	})

	it("sets state.back when user presses Esc in the prompt", async () => {
		readApiKeyFromConfigFileMock.mockReturnValue(undefined)
		passwordMock.mockResolvedValue({ kind: "back" })

		await runAuthStep(state, { backable: true })

		expect(state.back).toBe(true)
		expect(authenticateViaBrowserMock).not.toHaveBeenCalled()
	})

	it("sets state.cancelled when user presses Ctrl-C", async () => {
		readApiKeyFromConfigFileMock.mockReturnValue(undefined)
		passwordMock.mockResolvedValue({ kind: "cancel" })

		await runAuthStep(state, { backable: true })

		expect(state.cancelled).toBe(true)
	})
})

import type { Api, Model } from "@earendil-works/pi-ai"
import type { ModelRegistry } from "@earendil-works/pi-coding-agent"
import { describe, expect, it } from "vitest"
import { KIMCHI_DEV_PROVIDER, MODEL_CAPABILITIES } from "../orchestration/model-registry/index.js"
import { resolveClassifierModel } from "./classifier-model.js"

/** Minimal Model stub — only the fields resolveClassifierModel inspects. */
function fakeModel(
	provider: string,
	id = "test-model",
	cost = { input: 10, output: 30, cacheRead: 0, cacheWrite: 0 },
): Model<Api> {
	return { provider, id, cost } as Model<Api>
}

/** Minimal ModelRegistry stub with controllable find() and getAvailable(). */
function fakeRegistry(findResult: Model<Api> | undefined = undefined, available: Model<Api>[] = []): ModelRegistry {
	return { find: () => findResult, getAvailable: () => available } as unknown as ModelRegistry
}

/** The first light-tier model ID in MODEL_CAPABILITIES. */
const LIGHT_MODEL_ID = [...MODEL_CAPABILITIES.entries()].find(
	([, caps]) => caps !== "ignored" && caps.tier === "light",
)?.[0]

describe("resolveClassifierModel", () => {
	it("returns undefined when currentModel is undefined", () => {
		expect(resolveClassifierModel(undefined, fakeRegistry())).toBeUndefined()
	})

	describe("non-kimchi-dev provider", () => {
		it("steps down two cost tiers when three cheaper models exist", () => {
			const opus = fakeModel("anthropic", "claude-opus", { input: 15, output: 75, cacheRead: 0, cacheWrite: 0 })
			const sonnet = fakeModel("anthropic", "claude-sonnet", { input: 3, output: 15, cacheRead: 0, cacheWrite: 0 })
			const haiku = fakeModel("anthropic", "claude-haiku", { input: 0.25, output: 1.25, cacheRead: 0, cacheWrite: 0 })
			const nano = fakeModel("anthropic", "claude-nano", { input: 0.1, output: 0.4, cacheRead: 0, cacheWrite: 0 })

			const registry = fakeRegistry(undefined, [opus, sonnet, haiku, nano])
			const result = resolveClassifierModel(opus, registry)
			// Two steps down from opus: sonnet → haiku.
			expect(result).toBe(haiku)
		})

		it("steps down one tier when only one cheaper model exists", () => {
			const current = fakeModel("openai", "gpt-4o", { input: 5, output: 15, cacheRead: 0, cacheWrite: 0 })
			const mini = fakeModel("openai", "gpt-4o-mini", { input: 0.15, output: 0.6, cacheRead: 0, cacheWrite: 0 })

			const registry = fakeRegistry(undefined, [current, mini])
			const result = resolveClassifierModel(current, registry)
			expect(result).toBe(mini)
		})

		it("steps down exactly two when only two cheaper models exist", () => {
			const opus = fakeModel("anthropic", "claude-opus", { input: 15, output: 75, cacheRead: 0, cacheWrite: 0 })
			const sonnet = fakeModel("anthropic", "claude-sonnet", { input: 3, output: 15, cacheRead: 0, cacheWrite: 0 })
			const haiku = fakeModel("anthropic", "claude-haiku", { input: 0.25, output: 1.25, cacheRead: 0, cacheWrite: 0 })

			const registry = fakeRegistry(undefined, [opus, sonnet, haiku])
			const result = resolveClassifierModel(opus, registry)
			expect(result).toBe(haiku)
		})

		it("ignores models from other providers", () => {
			const current = fakeModel("openai", "gpt-4o", { input: 5, output: 15, cacheRead: 0, cacheWrite: 0 })
			const cheapOther = fakeModel("anthropic", "claude-haiku", {
				input: 0.25,
				output: 1.25,
				cacheRead: 0,
				cacheWrite: 0,
			})
			const sameProvider = fakeModel("openai", "gpt-4o-mini", { input: 0.15, output: 0.6, cacheRead: 0, cacheWrite: 0 })

			const registry = fakeRegistry(undefined, [current, cheapOther, sameProvider])
			const result = resolveClassifierModel(current, registry)
			expect(result).toBe(sameProvider)
		})

		it("picks the least expensive more-expensive model when current is already the cheapest", () => {
			const current = fakeModel("openai", "gpt-4o-mini", { input: 0.15, output: 0.6, cacheRead: 0, cacheWrite: 0 })
			const mid = fakeModel("openai", "gpt-4o", { input: 5, output: 15, cacheRead: 0, cacheWrite: 0 })
			const expensive = fakeModel("openai", "o3", { input: 10, output: 40, cacheRead: 0, cacheWrite: 0 })

			const registry = fakeRegistry(undefined, [current, mid, expensive])
			const result = resolveClassifierModel(current, registry)
			// Should pick gpt-4o (least expensive among more-expensive), not o3.
			expect(result).toBe(mid)
		})

		it("picks a different model even when all same-provider models cost the same", () => {
			const current = fakeModel("openai", "gpt-4o", { input: 5, output: 15, cacheRead: 0, cacheWrite: 0 })
			const twin = fakeModel("openai", "gpt-4o-copy", { input: 5, output: 15, cacheRead: 0, cacheWrite: 0 })

			const registry = fakeRegistry(undefined, [current, twin])
			const result = resolveClassifierModel(current, registry)
			expect(result).toBe(twin)
		})

		it("falls back to current model only when it is the sole model in the provider", () => {
			const current = fakeModel("openai", "gpt-4o")
			const registry = fakeRegistry(undefined, [current])

			const result = resolveClassifierModel(current, registry)
			expect(result).toBe(current)
		})

		it("falls back to current model when no models from the same provider are available", () => {
			const current = fakeModel("openai", "gpt-4o")
			const registry = fakeRegistry(undefined, [])

			const result = resolveClassifierModel(current, registry)
			expect(result).toBe(current)
		})

		it("does not call registry.find for a non-kimchi-dev provider", () => {
			const calls: string[] = []
			const model = fakeModel("openai", "gpt-4o")
			const registry = {
				find: (_provider: string, id: string) => {
					calls.push(id)
					return undefined
				},
				getAvailable: () => [model],
			} as unknown as ModelRegistry

			resolveClassifierModel(model, registry)
			expect(calls).toHaveLength(0)
		})
	})

	describe("kimchi-dev provider", () => {
		it("returns a light-tier model from the registry when current is not light", () => {
			const lightModel = fakeModel(KIMCHI_DEV_PROVIDER, LIGHT_MODEL_ID)
			const current = fakeModel(KIMCHI_DEV_PROVIDER, "kimi-k2.6")
			const registry = fakeRegistry(lightModel)

			const result = resolveClassifierModel(current, registry)
			expect(result).toBe(lightModel)
			expect(result?.id).toBe(LIGHT_MODEL_ID)
		})

		it("returns a different light-tier model when current is already light-tier", () => {
			const current = fakeModel(KIMCHI_DEV_PROVIDER, LIGHT_MODEL_ID)
			const otherLight = fakeModel(KIMCHI_DEV_PROVIDER, "other-light")

			// Registry returns otherLight for the light-tier ID lookup
			// We need a registry that returns different models for different IDs.
			const lightIds = [...MODEL_CAPABILITIES.entries()]
				.filter(([, caps]) => caps !== "ignored" && caps.tier === "light")
				.map(([id]) => id)

			// If there's only one light-tier in capabilities, we need to test
			// the "step up to next tier" path instead.
			if (lightIds.length <= 1) {
				// Current is the sole light-tier model. Registry should find a
				// standard-tier model as fallback.
				const standardId = [...MODEL_CAPABILITIES.entries()].find(
					([, caps]) => caps !== "ignored" && caps.tier === "standard",
				)?.[0]

				const standardModel = fakeModel(KIMCHI_DEV_PROVIDER, standardId ?? "standard-fallback")
				const registry = {
					find: (_p: string, id: string) => {
						if (id === LIGHT_MODEL_ID) return current
						if (standardId && id === standardId) return standardModel
						return undefined
					},
					getAvailable: () => [],
				} as unknown as ModelRegistry

				const result = resolveClassifierModel(current, registry)
				expect(result).not.toBe(current)
				expect(result?.id).toBe(standardModel.id)
			} else {
				// Multiple light-tier models exist — should pick the other one.
				const otherId = lightIds.find((id) => id !== LIGHT_MODEL_ID)
				const registry = {
					find: (_p: string, id: string) => {
						if (id === LIGHT_MODEL_ID) return current
						if (otherId && id === otherId) return otherLight
						return undefined
					},
					getAvailable: () => [],
				} as unknown as ModelRegistry

				const result = resolveClassifierModel(current, registry)
				expect(result).not.toBe(current)
			}
		})

		it("steps up to next tier when current is the sole light-tier model", () => {
			const current = fakeModel(KIMCHI_DEV_PROVIDER, LIGHT_MODEL_ID)
			const standardId = [...MODEL_CAPABILITIES.entries()].find(
				([, caps]) => caps !== "ignored" && caps.tier === "standard",
			)?.[0]

			const standardModel = fakeModel(KIMCHI_DEV_PROVIDER, standardId ?? "standard-fallback")
			const registry = {
				find: (_p: string, id: string) => {
					if (id === LIGHT_MODEL_ID) return current
					if (standardId && id === standardId) return standardModel
					return undefined
				},
				getAvailable: () => [],
			} as unknown as ModelRegistry

			const result = resolveClassifierModel(current, registry)
			expect(result).not.toBe(current)
		})

		it("falls back to current model only when no other models are available", () => {
			const current = fakeModel(KIMCHI_DEV_PROVIDER, "kimi-k2.6")
			const registry = fakeRegistry(undefined)

			const result = resolveClassifierModel(current, registry)
			expect(result).toBe(current)
		})

		it("calls registry.find with kimchi-dev provider and a light-tier model ID", () => {
			const calls: Array<{ provider: string; id: string }> = []
			const registry = {
				find: (provider: string, id: string) => {
					calls.push({ provider, id })
					return undefined
				},
				getAvailable: () => [],
			} as unknown as ModelRegistry

			const current = fakeModel(KIMCHI_DEV_PROVIDER, "kimi-k2.6")
			resolveClassifierModel(current, registry)

			// Should have searched for at least one light-tier model.
			expect(calls.length).toBeGreaterThan(0)
			expect(calls.every((c) => c.provider === KIMCHI_DEV_PROVIDER)).toBe(true)
			expect(calls.some((c) => c.id === LIGHT_MODEL_ID)).toBe(true)
		})
	})
})

import { describe, expect, it, vi } from "vitest"
import { RemoteNetworkError } from "../types.js"
import { authenticateRemoteSession, getMe, listRemoteSessions, waitForSessionReady } from "./index.js"
import { RemoteAuthError } from "./types.js"

const BASE = "https://api.example.com"

function mockFetch(url: string, opts: RequestInit): ReturnType<typeof globalThis.fetch>
function mockFetch(...args: unknown[]): never {
	throw new Error(`Unexpected fetch: ${args[0]}`)
}

describe("authenticateRemoteSession", () => {
	it("returns AuthenticateResponse on success after the 3-step flow", async () => {
		const mockFetch = vi
			.fn()
			// Step 1: verifyApiKey
			.mockResolvedValueOnce(
				new Response(JSON.stringify({ organizationId: "org-516442fe-054a-49e2-ac2d-9dc9b104c3d2" }), {
					status: 200,
					headers: { "Content-Type": "application/json" },
				}),
			)
			// Step 2: createOrUpdateSession
			.mockResolvedValueOnce(
				new Response(
					JSON.stringify({
						createTime: "2026-05-15T12:41:40.295Z",
						id: "sess-123",
						organizationId: "org-516442fe-054a-49e2-ac2d-9dc9b104c3d2",
						status: "INITIALIZING",
						uri: "wss://s-3380b7aa-981b-4272-8f7d-d6e41f62139f.remote.kimchi.dev",
					}),
					{ status: 200, headers: { "Content-Type": "application/json" } },
				),
			)
			// Step 3: exchangeSessionToken
			.mockResolvedValueOnce(
				new Response(
					JSON.stringify({
						token: "jwt-token-abc",
						expireTime: "2026-05-15T12:44:51.521Z",
					}),
					{ status: 200, headers: { "Content-Type": "application/json" } },
				),
			)

		const result = await authenticateRemoteSession("sess-123", "key1", "test session", {
			endpoint: BASE,
			fetch: mockFetch,
		})

		expect(result.connectToken).toBe("jwt-token-abc")
		expect(result.expiresAt).toBe("2026-05-15T12:44:51.521Z")
		expect(result.wsUrl).toBe("wss://s-3380b7aa-981b-4272-8f7d-d6e41f62139f.remote.kimchi.dev")
		expect(result.host).toBe("s-3380b7aa-981b-4272-8f7d-d6e41f62139f.remote.kimchi.dev")

		expect(mockFetch).toHaveBeenCalledTimes(3)
		expect(mockFetch.mock.calls[0][0]).toBe(`${BASE}/ai-optimizer/v1beta/api-keys:verify`)
		expect(mockFetch.mock.calls[0][1]).toMatchObject({
			method: "POST",
			headers: expect.objectContaining({
				Authorization: "Bearer key1",
				"Content-Type": "application/json",
			}),
		})
		expect(mockFetch.mock.calls[1][0]).toBe(
			`${BASE}/ai-optimizer/v1beta/organizations/org-516442fe-054a-49e2-ac2d-9dc9b104c3d2/sessions/sess-123`,
		)
		expect(mockFetch.mock.calls[1][1]).toMatchObject({
			method: "PUT",
			headers: expect.objectContaining({
				Authorization: "Bearer key1",
				"Content-Type": "application/json",
			}),
		})
		expect(mockFetch.mock.calls[2][0]).toBe(`${BASE}/ai-optimizer/v1beta/session-tokens:exchange`)
		expect(mockFetch.mock.calls[2][1]).toMatchObject({
			method: "POST",
			headers: expect.objectContaining({
				Authorization: "Bearer key1",
			}),
			body: JSON.stringify({ sessionId: "sess-123" }),
		})
	})

	it("uses explicit endpoint override for all steps", async () => {
		const mockFetch = vi
			.fn()
			.mockResolvedValueOnce(
				new Response(JSON.stringify({ organizationId: "org-1" }), {
					status: 200,
					headers: { "Content-Type": "application/json" },
				}),
			)
			.mockResolvedValueOnce(
				new Response(JSON.stringify({ uri: "wss://override.ws" }), {
					status: 200,
					headers: { "Content-Type": "application/json" },
				}),
			)
			.mockResolvedValueOnce(
				new Response(JSON.stringify({ token: "t", expireTime: "2025-01-01T00:00:00Z" }), {
					status: 200,
					headers: { "Content-Type": "application/json" },
				}),
			)

		await authenticateRemoteSession("s1", "key1", "test session", {
			endpoint: "https://override.example.com",
			fetch: mockFetch,
		})
		for (const call of mockFetch.mock.calls) {
			const url = call[0] as string
			expect(url.startsWith("https://override.example.com/")).toBe(true)
		}
	})

	it("throws RemoteAuthError for 401 on verify", async () => {
		const mockFetch = vi.fn().mockResolvedValue(new Response(null, { status: 401 }))
		await expect(
			authenticateRemoteSession("s1", "key1", "test session", { endpoint: BASE, fetch: mockFetch }),
		).rejects.toBeInstanceOf(RemoteAuthError)
	})

	it("throws RemoteAuthError for 401 on create session", async () => {
		const mockFetch = vi
			.fn()
			.mockResolvedValueOnce(
				new Response(JSON.stringify({ organizationId: "org-1" }), {
					status: 200,
					headers: { "Content-Type": "application/json" },
				}),
			)
			.mockResolvedValueOnce(new Response(null, { status: 401 }))

		await expect(
			authenticateRemoteSession("s1", "key1", "test session", { endpoint: BASE, fetch: mockFetch }),
		).rejects.toBeInstanceOf(RemoteAuthError)
	})

	it("throws RemoteAuthError for 401 on exchange token", async () => {
		const mockFetch = vi
			.fn()
			.mockResolvedValueOnce(
				new Response(JSON.stringify({ organizationId: "org-1" }), {
					status: 200,
					headers: { "Content-Type": "application/json" },
				}),
			)
			.mockResolvedValueOnce(
				new Response(JSON.stringify({ uri: "wss://x.ws" }), {
					status: 200,
					headers: { "Content-Type": "application/json" },
				}),
			)
			.mockResolvedValueOnce(new Response(null, { status: 401 }))

		await expect(
			authenticateRemoteSession("s1", "key1", "test session", { endpoint: BASE, fetch: mockFetch }),
		).rejects.toBeInstanceOf(RemoteAuthError)
	})

	it("throws RemoteAuthError for 403", async () => {
		const mockFetch = vi.fn().mockResolvedValue(new Response(null, { status: 403 }))
		await expect(
			authenticateRemoteSession("s1", "key1", "test session", { endpoint: BASE, fetch: mockFetch }),
		).rejects.toBeInstanceOf(RemoteAuthError)
	})

	it("throws RemoteAuthError for 404", async () => {
		const mockFetch = vi.fn().mockResolvedValue(new Response(null, { status: 404 }))
		await expect(
			authenticateRemoteSession("s1", "key1", "test session", { endpoint: BASE, fetch: mockFetch }),
		).rejects.toBeInstanceOf(RemoteAuthError)
	})

	it("throws RemoteAuthError for 409", async () => {
		const mockFetch = vi.fn().mockResolvedValue(new Response(null, { status: 409 }))
		await expect(
			authenticateRemoteSession("s1", "key1", "test session", { endpoint: BASE, fetch: mockFetch }),
		).rejects.toBeInstanceOf(RemoteAuthError)
	})

	it("throws RemoteNetworkError for other HTTP status", async () => {
		const mockFetch = vi.fn().mockResolvedValue(new Response(null, { status: 500 }))
		await expect(
			authenticateRemoteSession("s1", "key1", "test session", { endpoint: BASE, fetch: mockFetch }),
		).rejects.toBeInstanceOf(RemoteNetworkError)
	})

	it("throws RemoteNetworkError on fetch failure", async () => {
		const mockFetch = vi.fn().mockRejectedValue(new TypeError("fetch failed"))
		await expect(
			authenticateRemoteSession("s1", "key1", "test session", { endpoint: BASE, fetch: mockFetch }),
		).rejects.toBeInstanceOf(RemoteNetworkError)
	})

	it("throws RemoteNetworkError when verify response is missing organizationId", async () => {
		const mockFetch = vi.fn().mockResolvedValue(
			new Response(JSON.stringify({}), {
				status: 200,
				headers: { "Content-Type": "application/json" },
			}),
		)

		await expect(
