const ORG_ID = "org-516442fe-054a-49e2-ac2d-9dc9b104c3d2"

function verifyResponse() {
	return new Response(JSON.stringify({ organizationId: ORG_ID }), {
		status: 200,
		headers: { "Content-Type": "application/json" },
