describe("waitForSessionReady (WS probe)", () => {
	// Minimal WebSocket fake: records the URL + headers it was constructed with,
	// then a test directly fires `open` / `close` / `error` to simulate server behavior.
	type WSEvent = "open" | "close" | "error"
	class FakeWS {
		readonly url: string
		readonly opts: { headers?: Record<string, string> } | undefined
		readonly listeners = new Map<WSEvent, Array<(e: unknown) => void>>()
		closed = false
		constructor(url: string, opts?: { headers?: Record<string, string> }) {
			this.url = url
			this.opts = opts
		}
		addEventListener(type: WSEvent, cb: (e: unknown) => void) {
			const list = this.listeners.get(type) ?? []
			list.push(cb)
			this.listeners.set(type, list)
		}
		removeEventListener() {
			/* unused in these tests */
		}
		close() {
			this.closed = true
		}
		fire(type: WSEvent, payload: unknown = {}) {
			for (const cb of this.listeners.get(type) ?? []) cb(payload)
		}
	}

	function wsFactory() {
		const created: FakeWS[] = []
		const ctor = function (this: unknown, url: string, opts?: { headers?: Record<string, string> }) {
			const ws = new FakeWS(url, opts)
			created.push(ws)
			return ws
		} as unknown as new (
			url: string,
			opts?: { headers?: Record<string, string> },
		) => FakeWS
		return { created, ctor }
	}

	it("resolves on the first probe that opens", async () => {
		const { created, ctor } = wsFactory()

		const promise = waitForSessionReady({
			wsUrl: "wss://h.example.com/",
			connectToken: "tok-1",
			pollIntervalMs: 1,
			probeTimeoutMs: 1000,
			_WebSocket: ctor,
		})

		// Wait one microtask for the first probe to register its listeners.
		await Promise.resolve()
		await Promise.resolve()
		expect(created).toHaveLength(1)
		expect(created[0].url).toBe("wss://h.example.com//connect")
		expect(created[0].opts?.headers).toEqual({ Authorization: "Bearer tok-1" })

		created[0].fire("open")
		await expect(promise).resolves.toBeUndefined()
		expect(created[0].closed).toBe(true)
	})

	it("retries when the first probe closes with a non-101", async () => {
		const { created, ctor } = wsFactory()

		const promise = waitForSessionReady({
			wsUrl: "wss://h.example.com/",
			connectToken: "tok",
			pollIntervalMs: 1,
			probeTimeoutMs: 1000,
			_WebSocket: ctor,
		})

		// First probe closes with 1002 (non-101).
		await Promise.resolve()
		await Promise.resolve()
		created[0].fire("close", { code: 1002, reason: "not yet" })

		// Wait long enough for the second probe to start.
		await new Promise((r) => setTimeout(r, 10))
		expect(created.length).toBeGreaterThanOrEqual(2)
		created[1].fire("open")

		await expect(promise).resolves.toBeUndefined()
	})

	it("fires onTick for each probe with the lastError on failure", async () => {
		const { created, ctor } = wsFactory()
		const ticks: Array<{ elapsedMs: number; lastError?: string }> = []

		const promise = waitForSessionReady({
			wsUrl: "wss://h.example.com/",
			connectToken: "tok",
			pollIntervalMs: 1,
			probeTimeoutMs: 1000,
			onTick: (t) => ticks.push(t),
			_WebSocket: ctor,
		})

		await Promise.resolve()
		await Promise.resolve()
		created[0].fire("close", { code: 1002 })
		await new Promise((r) => setTimeout(r, 10))
		created[1].fire("open")
		await promise

		expect(ticks).toHaveLength(2)
		expect(ticks[0].lastError).toMatch(/code=1002/)
		expect(ticks[1].lastError).toBeUndefined()
	})

	it("rejects on overall timeout with the last probe error in the message", async () => {
		const { created, ctor } = wsFactory()

		const promise = waitForSessionReady({
			wsUrl: "wss://h.example.com/",
			connectToken: "tok",
			pollIntervalMs: 5,
			probeTimeoutMs: 2,
			timeoutMs: 30,
			_WebSocket: ctor,
		})

		// Fire close on every probe as it appears.
		const loop = setInterval(() => {
			const latest = created[created.length - 1]
			if (latest && !latest.closed) latest.fire("close", { code: 1002 })
		}, 1)

		await expect(promise).rejects.toThrow(/code=1002/)
		clearInterval(loop)
	})

	it("rejects when the abort signal fires", async () => {
		const { ctor } = wsFactory()
		const ctrl = new AbortController()

		const promise = waitForSessionReady({
			wsUrl: "wss://h.example.com/",
			connectToken: "tok",
			pollIntervalMs: 60_000,
			probeTimeoutMs: 60_000,
			signal: ctrl.signal,
			_WebSocket: ctor,
		})

		setTimeout(() => ctrl.abort(), 5)
		await expect(promise).rejects.toThrow(/[Aa]borted/)
	})

	it("throws when no WebSocket implementation is available", async () => {
		await expect(
			waitForSessionReady({
				wsUrl: "wss://h.example.com/",
				connectToken: "tok",
				// biome-ignore lint/suspicious/noExplicitAny: simulate missing WebSocket
				_WebSocket: undefined as any,
			}),
		).rejects.toThrow(/WebSocket is not available/)
	})
})

/**
 * Cache and resolver integration tests.
 *
 * Exercises the on-disk metadata cache + `resolveDirectTools` pipeline that the
 * MCP direct-tools registration depends on. Each test gets a fresh temp
 * `KIMCHI_CODING_AGENT_DIR` and re-imports the cache module so the memoized
 * cache path (`metadata-cache.ts:13`) picks up the per-test env override.
 *
 * Scope intentionally stops at the cache + resolver layer:
 *   - End-to-end `initializeMcp` bootstrap requires either a real MCP server
 *     subprocess or a `McpServerManager` injection refactor; both are out of
 *     scope for this PR.
 *   - `registerAndActivate(..., { markDynamic: false })` needs a stub
 *     `ExtensionAPI`; that helper warrants its own file and follow-up.
 */

import { mkdtempSync, rmSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest"
import type { McpConfig, ServerEntry } from "./types.js"

// Module surface — typed via import type so the dynamic imports below stay
// strongly typed without locking in a single module instance.
type CacheModule = typeof import("./metadata-cache.js")
type DirectToolsModule = typeof import("./direct-tools.js")

// ─── Test harness ─────────────────────────────────────────────────────────────

interface Harness {
	cacheModule: CacheModule
	directToolsModule: DirectToolsModule
	cachePath: string
}

let tempHome: string | undefined
let originalEnv: string | undefined

/**
 * Set up a fresh temp agent directory and re-import the cache + resolver
 * modules so their module-level memoization picks up the new
 * `KIMCHI_CODING_AGENT_DIR`.
 */
async function buildHarness(): Promise<Harness> {
	tempHome = mkdtempSync(join(tmpdir(), "mcp-cache-test-"))
	process.env.KIMCHI_CODING_AGENT_DIR = tempHome

	vi.resetModules()
	const cacheModule = await import("./metadata-cache.js")
	const directToolsModule = await import("./direct-tools.js")
	return {
		cacheModule,
		directToolsModule,
		cachePath: join(tempHome, "mcp-cache.json"),
	}
}

beforeEach(() => {
	originalEnv = process.env.KIMCHI_CODING_AGENT_DIR
})

afterEach(() => {
	if (originalEnv === undefined) delete process.env.KIMCHI_CODING_AGENT_DIR
	else process.env.KIMCHI_CODING_AGENT_DIR = originalEnv
	if (tempHome) {
		rmSync(tempHome, { recursive: true, force: true })
		tempHome = undefined
	}
})

