import { describe, expect, it } from "vitest"
import {
	createBudgetRetryBlock,
	createBudgetRetryBlockFromCompletion,
	shouldBlockBudgetRetry,
} from "./budget-retry-guard.js"

describe("budget retry guard", () => {
	it("blocks a higher-budget retry of the same failed call", () => {
		const block = createBudgetRetryBlock({
			budget: 100,
			subagentType: "Explore",
			description: "Explore agent extension",
			prompt: "inspect repository",
		})

		expect(
			shouldBlockBudgetRetry(block, {
				tokenBudget: 1_000,
				subagentType: "Explore",
				description: "Explore agent extension",
				prompt: "inspect repository",
			}),
		).toBe(true)
	})

	it("allows a different agent type requested in the same user turn", () => {
		const block = createBudgetRetryBlock({
			budget: 100,
			subagentType: "Explore",
			description: "Explore agent extension",
			prompt: "inspect repository",
		})

		expect(
			shouldBlockBudgetRetry(block, {
				tokenBudget: 1_000,
				subagentType: "Plan",
				description: "Plan agent extension",
				prompt: "inspect repository",
			}),
		).toBe(false)
	})

	it("allows a different task for the same agent type", () => {
		const block = createBudgetRetryBlock({
			budget: 100,
			subagentType: "Explore",
			description: "Explore agent extension",
			prompt: "inspect repository",
		})

		expect(
			shouldBlockBudgetRetry(block, {
				tokenBudget: 1_000,
				subagentType: "Explore",
				description: "Explore package metadata",
				prompt: "inspect package metadata",
			}),
		).toBe(false)
	})

	it("creates a retry block when a background completion reports token budget abort", () => {
		const block = createBudgetRetryBlockFromCompletion(
			{
				budget: 100,
				subagentType: "Explore",
				description: "Explore agent extension",
				prompt: "inspect repository",
			},
			{ status: "aborted", abortReason: "token_budget" },
		)

		expect(block).toMatchObject({
			budget: 100,
			subagentType: "Explore",
			normalizedDescription: "explore agent extension",
			normalizedPrompt: "inspect repository",
		})
	})

	it("does not create a retry block for non-budget completions", () => {
		const candidate = {
			budget: 100,
			subagentType: "Explore",
			description: "Explore agent extension",
			prompt: "inspect repository",
		}

		expect(createBudgetRetryBlockFromCompletion(candidate, { status: "completed" })).toBeUndefined()
		expect(
			createBudgetRetryBlockFromCompletion(candidate, { status: "aborted", abortReason: "max_turns" }),
		).toBeUndefined()
	})
})

import { spinner } from "@clack/prompts"
import { validateApiKey } from "../../auth/validator.js"
import { authenticateViaBrowser } from "../../cli-auth/index.js"
import { readApiKeyFromConfigFile, writeApiKey } from "../../config.js"
import { confirm, password } from "../prompt.js"
import type { WizardState } from "../state.js"

/**
 * Auth step — secure an API key for the rest of the wizard. Two frames:
 *
 *   1. **Saved-key frame** — when a key is already available (env var or
 *      ~/.config/kimchi/config.json), offer "use saved / enter new" (Y/n).
 *      On Y the existing key is validated and accepted; on N we fall
 *      through to the input frame so the user can replace it.
 *   2. **Input frame** — prompt for a key, validate, retry on failure
 *      (with the validator's suggestions printed). On success the key is
 *      written to config.json so future runs land in frame 1.
 *
 * The wizard's persistence is split with runDoneStep: this step writes
 * a newly-entered key to ~/.config/kimchi/config.json; runDoneStep then
 * exports state.apiKey to the user's shell profile so future shells see
 * $KIMCHI_API_KEY automatically. The current shell session keeps
 * whatever $KIMCHI_API_KEY was set to on entry until it's reloaded or
 * unset.
 */
export async function runAuthStep(state: WizardState, opts: { backable: boolean }): Promise<void> {
	const envKey = process.env.KIMCHI_API_KEY
	const fileKey = readApiKeyFromConfigFile()
	const fromEnv = !!(envKey && envKey.length > 0)
	const currentKey = fromEnv ? (envKey as string) : (fileKey ?? "")

	if (currentKey.length > 0) {
		const r = await confirm({
			message: "An API key is already configured. Keep it?",
			initialValue: true,
			backable: opts.backable,
		})
		if (r.kind === "back") {
			state.back = true
			return
		}
		if (r.kind === "cancel") {
			state.cancelled = true
			return
		}
		if (r.value) {
			const s = spinner()
			s.start("Validating saved API key…")
			const result = await validateApiKey(currentKey)
			if (result.valid) {
				s.stop("Saved API key valid.")
				state.apiKey = currentKey
				return
			}
			s.stop(`Saved key failed validation: ${result.error ?? "unknown error"}`)
			console.log("  Replace it below, press Esc to go back, or Ctrl-C to abort.")
		} else if (fromEnv) {
			console.log(
				"  Note: this shell still has $KIMCHI_API_KEY set; the new key will be written to config.json and your shell profile, so new shells pick it up automatically. To use it here, run 'unset KIMCHI_API_KEY' or open a new terminal.",
			)
		}
	}

	await promptAndValidateKey(state, opts.backable)
}

async function promptAndValidateKey(state: WizardState, backable: boolean): Promise<void> {
	for (;;) {
		const entered = await password({
			message: "Paste your Kimchi API key, or press Enter to log in via browser",
			backable,
		})
		if (entered.kind === "back") {
			state.back = true
			return
		}
		if (entered.kind === "cancel") {
			state.cancelled = true
			return
		}

		let tokenToValidate: string

		if (entered.value.length === 0) {
			// Browser-based authentication — token was just created by the backend,
			// so it's valid. Skip the separate validation roundtrip, which may
			// hit a different environment (e.g. prod validator vs dev-master token).
			const s = spinner()
			s.start("Waiting for browser login…")
			let token: string
			try {
				const result = await authenticateViaBrowser()
				token = result.token
				s.stop("Browser login succeeded.")
			} catch (err) {
				s.stop("Browser login failed.")
				console.error(`  ${err instanceof Error ? err.message : String(err)}`)
				console.log("  Paste your API key below, or press Esc to go back.")
				continue
			}

			try {
				writeApiKey(token)
			} catch (err) {
				console.error(`  Failed to save API key to config: ${err instanceof Error ? err.message : String(err)}`)
				console.log("  Paste your API key below, or press Esc to go back.")
				continue
			}

			state.apiKey = token
			return
		}

		tokenToValidate = entered.value

		const s = spinner()
		s.start("Validating API key…")
		const result = await validateApiKey(tokenToValidate)
		if (result.valid) {
			s.stop("API key valid.")
			state.apiKey = tokenToValidate
			writeApiKey(state.apiKey)
			return
		}
		s.stop(`Validation failed: ${result.error ?? "unknown error"}`)
		for (const sug of result.suggestions ?? ["Try a different key, press Esc to go back, or Ctrl-C to abort."]) {
			console.log(`  - ${sug}`)
		}
	}
}

import type { Api, Model } from "@earendil-works/pi-ai"
import type { ModelRegistry } from "@earendil-works/pi-coding-agent"
import { KIMCHI_DEV_PROVIDER, MODEL_CAPABILITIES } from "../orchestration/model-registry/index.js"
import type { ModelTier } from "../orchestration/model-registry/types.js"

/** Tier ordering from cheapest to most expensive. */
const TIER_RANK: Record<ModelTier, number> = { light: 0, standard: 1, heavy: 2 }

/**
 * Compute a single scalar cost for a model so we can compare cheapness.
 * Uses the sum of input and output per-token costs.
 */
function modelCost(model: Model<Api>): number {
	return (model.cost?.input ?? 0) + (model.cost?.output ?? 0)
}

/**
 * Pick the model to use for the classifier.
 *
 * The goal is to always use a *different* model than the current one to
 * avoid wasting expensive tokens on a simple classification task. The
 * current model is only returned as a last resort when no other model
 * from the same provider is available.
 *
 * Strategy:
 *   - kimchi-dev provider: select the lightest-tier model from the
 *     orchestration model registry (MODEL_CAPABILITIES). If the current
 *     model is already light-tier, try another light-tier model first,
 *     then step up to the next tier. Falls back to the current model
 *     only when it is the sole available model.
 *   - Any other provider: step down up to two cost tiers within the same
 *     provider. If the current model is already the cheapest, pick the
 *     least expensive model that costs more. Falls back to the current
 *     model only when it is the sole available model.
 */
export function resolveClassifierModel(
	currentModel: Model<Api> | undefined,
	modelRegistry: ModelRegistry,
): Model<Api> | undefined {
	if (!currentModel) return undefined

	if (currentModel.provider !== KIMCHI_DEV_PROVIDER) {
		return cheaperFromSameProvider(currentModel, modelRegistry)
	}

	return resolveKimchiDevClassifier(currentModel, modelRegistry)
}

/**
 * Resolve a classifier model for the kimchi-dev provider.
 *
 * Preference order:
 *   1. A light-tier model that is NOT the current model.
 *   2. Any other light-tier model (even the current one — covered by step 1 only
 *      when there are multiple lights).
 *   3. The next tier up (standard, then heavy) — any model other than current.
 *   4. The current model as an absolute fallback.
 */
function resolveKimchiDevClassifier(currentModel: Model<Api>, modelRegistry: ModelRegistry): Model<Api> {
	const currentCaps = MODEL_CAPABILITIES.get(currentModel.id)
	const currentTier = currentCaps !== undefined && currentCaps !== "ignored" ? currentCaps.tier : undefined

	// 1. Try light-tier models, preferring one that is NOT the current model.
	const lightModels: Model<Api>[] = []
	for (const [id, caps] of MODEL_CAPABILITIES) {
		if (caps === "ignored") continue
		if (caps.tier === "light") {
			const resolved = modelRegistry.find(KIMCHI_DEV_PROVIDER, id)
			if (resolved) lightModels.push(resolved)
		}
	}

	const differentLight = lightModels.find((m) => m.id !== currentModel.id)
	if (differentLight) return differentLight

	// Current model is the only light-tier model — if current is already
	// light-tier, try the next tier up instead.
	if (currentTier === "light") {
		const nextUp = findNextTierUp(currentModel, modelRegistry, "light")
		if (nextUp) return nextUp
	}

	// Return the single light-tier model if one exists (even if it is current).
	if (lightModels.length > 0) return lightModels[0]

	// No light-tier available at all — fall back to current.
	return currentModel
}

/**
 * Find the lowest-cost model at the next tier above `belowTier` that is
 * not the current model.
 *
 * Tier ordering: light < standard < heavy.
 */
function findNextTierUp(
	currentModel: Model<Api>,
	modelRegistry: ModelRegistry,
	belowTier: ModelTier,
): Model<Api> | undefined {
	const tiersAscending: ModelTier[] = ["light", "standard", "heavy"]
	const startRank = TIER_RANK[belowTier] + 1

	for (const tier of tiersAscending) {
		if (TIER_RANK[tier] < startRank) continue
		for (const [id, caps] of MODEL_CAPABILITIES) {
			if (caps === "ignored") continue
			if (caps.tier === tier && id !== currentModel.id) {
				const resolved = modelRegistry.find(KIMCHI_DEV_PROVIDER, id)
				if (resolved) return resolved
			}
		}
	}

	return undefined
}

/**
 * Among all available models from the same provider, step down up to two
 * cost tiers from `currentModel`.
 *
 * If no cheaper model exists, pick the least more expensive model to
 * still avoid reusing the current model. Falls back to the current model
 * only when it is the sole available model from that provider.
 */
function cheaperFromSameProvider(currentModel: Model<Api>, modelRegistry: ModelRegistry): Model<Api> {
	const currentCost = modelCost(currentModel)

	const sameProvider = modelRegistry.getAvailable().filter((m) => m.provider === currentModel.provider)

	// Collect models that are strictly cheaper, sorted descending by cost.
	const cheaper = sameProvider.filter((m) => modelCost(m) < currentCost).sort((a, b) => modelCost(b) - modelCost(a))

	if (cheaper.length > 0) {
		// Step down up to 2 tiers: index 0 = one step, index 1 = two steps.
		const stepsDown = Math.min(1, cheaper.length - 1)
		return cheaper[stepsDown]
	}

	// No cheaper model — pick the least more expensive alternative to avoid
	// reusing the current model.
	const moreExpensive = sameProvider
		.filter((m) => m.id !== currentModel.id && modelCost(m) >= currentCost)
		.sort((a, b) => modelCost(a) - modelCost(b))

	if (moreExpensive.length > 0) return moreExpensive[0]

	// Sole model in the provider — no choice.
	return currentModel
}

/**
 * MCP Auth Flow
 *
 * High-level OAuth flow management using the MCP SDK's built-in auth functions.
 * Follows the OpenCode pattern: let the SDK handle discovery internally via transport.
 */

import { UnauthorizedError } from "@modelcontextprotocol/sdk/client/auth.js"
import { Client } from "@modelcontextprotocol/sdk/client/index.js"
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js"
import open from "open"
import {
	type StoredTokens,
	clearAllCredentials,
	clearOAuthState,
	getAuthForUrl,
	getOAuthState,
	hasStoredTokens,
	isTokenExpired,
	updateOAuthState,
} from "./mcp-auth.js"
import {
	cancelPendingCallback,
	ensureCallbackServer,
	stopCallbackServer,
	waitForCallback,
} from "./mcp-callback-server.js"
import { type McpOAuthConfig, McpOAuthProvider } from "./mcp-oauth-provider.js"
import type { ServerEntry } from "./types.js"

/** Auth status for a server */
export type AuthStatus = "authenticated" | "expired" | "not_authenticated"

// Track pending transports for auth completion
const pendingTransports = new Map<string, StreamableHTTPClientTransport>()

// Deduplicate concurrent authenticate() calls per server.
const pendingAuthentications = new Map<string, Promise<AuthStatus>>()

/**
 * Generate a cryptographically secure random state parameter.
 */
function generateState(): string {
	return Array.from(crypto.getRandomValues(new Uint8Array(32)))
		.map((b) => b.toString(16).padStart(2, "0"))
		.join("")
}

/**
 * Extract OAuth configuration from a ServerEntry.
 */
function extractOAuthConfig(definition: ServerEntry): McpOAuthConfig {
	// If oauth is explicitly false, return empty config
	if (definition.oauth === false) {
		return {}
	}
	return {
		grantType: definition.oauth?.grantType,
		clientId: definition.oauth?.clientId,
		clientSecret: definition.oauth?.clientSecret,
		scope: definition.oauth?.scope,
	}
}

/**
 * Start OAuth authentication flow for a server.
 * Returns the authorization URL that should be opened in a browser.
 *
 * This follows the OpenCode pattern:
 * 1. Create transport with auth provider
 * 2. Try to connect - SDK handles discovery internally
 * 3. If UnauthorizedError, capture the auth URL from onRedirect
 */
export async function startAuth(
	serverName: string,
	serverUrl: string,
	definition?: ServerEntry,
): Promise<{ authorizationUrl: string; transport: StreamableHTTPClientTransport }> {
	const config = definition ? extractOAuthConfig(definition) : {}

	if (config.grantType === "client_credentials") {
		const authProvider = new McpOAuthProvider(serverName, serverUrl, config, {
			onRedirect: async () => {
				throw new Error("Browser redirect is not used for client_credentials flow")
			},
		})
		const transport = new StreamableHTTPClientTransport(new URL(serverUrl), {
			authProvider,
		})
		const client = new Client({
			name: "pi-mcp",
			version: "3.0.0",
		})

		try {
			await client.connect(transport)
			return { authorizationUrl: "", transport }
		} finally {
			await client.close().catch(() => {})
			await transport.close().catch(() => {})
		}
	}

	// Start the callback server.
	// Pre-registered OAuth clients require an exact redirect URI, so enforce strict port binding.
	await ensureCallbackServer({ strictPort: Boolean(config.clientId) })

	// Generate and store OAuth state BEFORE creating the provider
	// The SDK will call provider.state() to read this value
	const oauthState = generateState()
	await updateOAuthState(serverName, oauthState)

	// Create the auth provider
	let capturedUrl: URL | undefined
	const authProvider = new McpOAuthProvider(serverName, serverUrl, config, {
		onRedirect: async (url) => {
			capturedUrl = url
		},
	})

	// Create transport with auth provider
	// The SDK handles OAuth discovery internally when connecting
	const transport = new StreamableHTTPClientTransport(new URL(serverUrl), {
		authProvider,
	})
	const client = new Client({
		name: "pi-mcp",
		version: "3.0.0",
	})

	// Try to connect - this triggers the OAuth flow
	try {
		await client.connect(transport)
		// If we get here, we're already authenticated
		await client.close().catch(() => {})
		await transport.close().catch(() => {})
		return { authorizationUrl: "", transport }
	} catch (error) {
		if (error instanceof UnauthorizedError && capturedUrl) {
			await client.close().catch(() => {})
			// Store transport for later finishAuth
			pendingTransports.set(serverName, transport)
			return { authorizationUrl: capturedUrl.toString(), transport }
		}
		await client.close().catch(() => {})
		await transport.close().catch(() => {})
		throw error
	}
}

/**
 * Complete OAuth authentication with the authorization code.
 */
export async function completeAuth(serverName: string, authorizationCode: string): Promise<AuthStatus> {
	const transport = pendingTransports.get(serverName)
	if (!transport) {
		throw new Error(`No pending OAuth flow for server: ${serverName}`)
	}

	try {
		// Complete the auth using the transport's finishAuth method
		await transport.finishAuth(authorizationCode)
		return "authenticated"
	} finally {
		pendingTransports.delete(serverName)
		await transport.close().catch(() => {})
	}
}

/**
 * Perform the complete OAuth authentication flow for a server.
 *
 * @param serverName - The name of the MCP server
 * @param serverUrl - The URL of the MCP server
 * @param definition - The server definition (optional)
 * @returns The final auth status
 */
export async function authenticate(
	serverName: string,
	serverUrl: string,
	definition?: ServerEntry,
): Promise<AuthStatus> {
	const inFlight = pendingAuthentications.get(serverName)
	if (inFlight) {
		return inFlight
	}

	const operation = (async (): Promise<AuthStatus> => {
		// Start auth flow
		const { authorizationUrl } = await startAuth(serverName, serverUrl, definition)

		// If no auth URL needed, already authenticated
		if (!authorizationUrl) {
			return "authenticated"
		}

		// Get the state that was already generated and stored in startAuth()
		const oauthState = await getOAuthState(serverName)
		if (!oauthState) {
			throw new Error("OAuth state not found - this should not happen")
		}

		// Register the callback BEFORE opening the browser
		const callbackPromise = waitForCallback(oauthState)

		// Open browser
		console.log(`MCP Auth: Opening browser for ${serverName}`)
		try {
			await open(authorizationUrl)
		} catch (error) {
			console.warn(`MCP Auth: Failed to open browser for ${serverName}`, { error })
			throw new Error(`Could not open browser. Please open this URL manually: ${authorizationUrl}`, { cause: error })
		}

		try {
			// Wait for callback
			const code = await callbackPromise

			// Validate state
			const storedState = await getOAuthState(serverName)
			if (storedState !== oauthState) {
				await clearOAuthState(serverName)
				throw new Error("OAuth state mismatch - potential CSRF attack")
			}
			await clearOAuthState(serverName)

			// Complete the auth
			return await completeAuth(serverName, code)
		} catch (error) {
			cancelPendingCallback(oauthState)
			const pendingTransport = pendingTransports.get(serverName)
			if (pendingTransport) {
				pendingTransports.delete(serverName)
				await pendingTransport.close().catch(() => {})
			}
			throw error
		}
	})()

	pendingAuthentications.set(serverName, operation)

	try {
		return await operation
	} finally {
		if (pendingAuthentications.get(serverName) === operation) {
			pendingAuthentications.delete(serverName)
		}
	}
}

/**
 * Get a valid access token for a server, refreshing if necessary.
 *
 * @param serverName - The name of the MCP server
 * @param serverUrl - The URL of the MCP server
 * @returns The valid tokens or null if not authenticated
 */
export async function getValidToken(serverName: string, serverUrl: string): Promise<StoredTokens | null> {
	// Check if we have valid tokens
	const entry = await getAuthForUrl(serverName, serverUrl)
	if (!entry?.tokens) {
		return null
	}

	// Check expiration
	const expired = await isTokenExpired(serverName)
	if (expired === false) {
		return entry.tokens
	}

	if (expired === true && entry.tokens.refreshToken) {
		// Token is expired, try to refresh
		console.log(`MCP Auth: Token expired for ${serverName}, attempting refresh`)

		try {
			// Create auth provider for token refresh
			const authProvider = new McpOAuthProvider(
				serverName,
				serverUrl,
				{},
				{
					onRedirect: async () => {},
				},
			)

			const clientInfo = await authProvider.clientInformation()
			if (!clientInfo) {
				console.log(`MCP Auth: No client info for refresh for ${serverName}`)
				return null
			}

			// Try to get tokens to find the token endpoint
			const existingTokens = await authProvider.tokens()
			if (!existingTokens) {
				return null
			}

			// Create transport to trigger refresh
			const transport = new StreamableHTTPClientTransport(new URL(serverUrl), {
				authProvider,
			})

			// Try to connect - SDK will attempt token refresh internally
			const client = new Client({ name: "pi-mcp", version: "3.0.0" })
			try {
				await client.connect(transport)
				// Get refreshed tokens
				const refreshed = await getAuthForUrl(serverName, serverUrl)
				return refreshed?.tokens ?? null
			} catch (error) {
				console.error(`MCP Auth: Token refresh failed for ${serverName}`, { error })
				return null
			} finally {
				await client.close().catch(() => {})
				await transport.close().catch(() => {})
			}
		} catch (error) {
			console.error(`MCP Auth: Token refresh failed for ${serverName}`, { error })
			return null
		}
	}

	// No expiration info or no refresh token, assume valid
	return entry.tokens
}

/**
 * Check the authentication status for a server.
 *
 * @param serverName - The name of the MCP server
 * @returns The current auth status
 */
export async function getAuthStatus(serverName: string): Promise<AuthStatus> {
	const hasTokens = await hasStoredTokens(serverName)
	if (!hasTokens) return "not_authenticated"

	const expired = await isTokenExpired(serverName)
	return expired ? "expired" : "authenticated"
}

/**
 * Remove all OAuth credentials for a server.
 *
 * @param serverName - The name of the MCP server
 */
export async function removeAuth(serverName: string): Promise<void> {
	const oauthState = await getOAuthState(serverName)
	if (oauthState) {
		cancelPendingCallback(oauthState)
	}
	const pendingTransport = pendingTransports.get(serverName)
	if (pendingTransport) {
		pendingTransports.delete(serverName)
		await pendingTransport.close().catch(() => {})
	}
	clearAllCredentials(serverName)
	await clearOAuthState(serverName)
	console.log(`MCP Auth: Removed credentials for ${serverName}`)
}

/**
 * Check if OAuth is supported for a server configuration.
 * OAuth is supported for HTTP servers unless explicitly disabled.
 *
 * @param definition - The server definition
 * @returns True if OAuth is supported
 */
export function supportsOAuth(definition: ServerEntry): boolean {
	// OAuth requires a URL
	if (!definition.url) return false

	// Explicitly disabled via auth: false or oauth: false
	if (definition.auth === false) return false
	if (definition.oauth === false) return false

	// OAuth is enabled if auth is 'oauth' or not specified (auto-detect)
	return definition.auth === "oauth" || definition.auth === undefined
}

/**
 * Initialize the OAuth system on startup.
 * Starts the callback server if there are any OAuth servers configured.
 */
export async function initializeOAuth(): Promise<void> {
	await ensureCallbackServer()
}

/**
 * Shutdown the OAuth system.
 * Stops the callback server and cancels pending auths.
 */
export async function shutdownOAuth(): Promise<void> {
	await stopCallbackServer()
}

/**
 * MCP Auth Storage Module
 *
 * Handles secure storage of OAuth credentials, tokens, client information,
 * and PKCE state for MCP servers. Maintains backward compatibility with
 * per-server directory structure.
 *
 * Token storage location: ~/.pi/agent/mcp-oauth/<server>/tokens.json
 */

import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "fs"
import { join } from "path"
import { getAgentDir } from "./utils.js"

/** OAuth token storage format */
export interface StoredTokens {
	accessToken: string
	refreshToken?: string
	expiresAt?: number // Unix timestamp in seconds
	scope?: string
}

/** OAuth client information from dynamic or static registration */
export interface StoredClientInfo {
	clientId: string
	clientSecret?: string
	clientIdIssuedAt?: number
	clientSecretExpiresAt?: number
}

/** Complete auth entry for a server */
export interface AuthEntry {
	tokens?: StoredTokens
	clientInfo?: StoredClientInfo
	codeVerifier?: string
	oauthState?: string
	serverUrl?: string // Track the URL these credentials are for
}

// Base directory for auth storage - can be overridden via env var for testing
function getAuthBaseDir(): string {
	return process.env.MCP_OAUTH_DIR ?? join(getAgentDir(), "mcp-oauth")
}

/**
 * Get the server-specific directory path.
 */
function getServerDir(serverName: string): string {
	return join(getAuthBaseDir(), serverName)
}

/**
 * Get the tokens file path for a server.
 */
function getTokensFilePath(serverName: string): string {
	return join(getServerDir(serverName), "tokens.json")
}

/**
 * Ensure the server directory exists with secure permissions.
 */
function ensureServerDir(serverName: string): void {
	const dir = getServerDir(serverName)
	if (!existsSync(dir)) {
		mkdirSync(dir, { recursive: true, mode: 0o700 })
	}
}

/**
 * Read the auth entry for a server from disk.
 * Returns undefined if file doesn't exist.
 */
function readAuthEntry(serverName: string): AuthEntry | undefined {
	try {
		const filePath = getTokensFilePath(serverName)
		if (!existsSync(filePath)) {
			return undefined
		}
		const data = readFileSync(filePath, "utf-8")
		return JSON.parse(data) as AuthEntry
	} catch (error) {
		console.error(`Failed to read auth entry for ${serverName}:`, error)
		return undefined
	}
}

/**
 * Write the auth entry for a server to disk with secure permissions.
 */
function writeAuthEntry(serverName: string, entry: AuthEntry): void {
	ensureServerDir(serverName)
	const filePath = getTokensFilePath(serverName)
	writeFileSync(filePath, JSON.stringify(entry, null, 2), { mode: 0o600 })
}

/**
 * Get auth entry for a server.
 */
export function getAuthEntry(serverName: string): AuthEntry | undefined {
	return readAuthEntry(serverName)
}

/**
 * Get auth entry and validate it's for the correct URL.
 * Returns undefined if URL has changed (credentials are invalid).
 */
export function getAuthForUrl(serverName: string, serverUrl: string): AuthEntry | undefined {
	const entry = getAuthEntry(serverName)
	if (!entry) return undefined

	// If no serverUrl is stored, this is from an old version - consider it invalid
	if (!entry.serverUrl) return undefined

	// If URL has changed, credentials are invalid
	if (entry.serverUrl !== serverUrl) return undefined

	return entry
}

/**
 * Save auth entry for a server.
 */
export function saveAuthEntry(serverName: string, entry: AuthEntry, serverUrl?: string): void {
	// Always update serverUrl if provided
	if (serverUrl) {
		entry.serverUrl = serverUrl
	}
	writeAuthEntry(serverName, entry)
}

/**
 * Remove auth entry for a server.
 * Also removes the server directory if empty.
 */
export function removeAuthEntry(serverName: string): void {
	try {
		const filePath = getTokensFilePath(serverName)
		if (existsSync(filePath)) {
			writeFileSync(filePath, "{}", { mode: 0o600 })
		}
		// Try to remove the directory
		const dir = getServerDir(serverName)
		if (existsSync(dir)) {
			try {
				rmSync(dir, { recursive: true })
			} catch {
				// Directory may not be empty, ignore
			}
		}
	} catch (error) {
		console.error(`Failed to remove auth entry for ${serverName}:`, error)
	}
}

/**
 * Update tokens for a server.
 */
export function updateTokens(serverName: string, tokens: StoredTokens, serverUrl?: string): void {
	const entry = getAuthEntry(serverName) ?? {}
	entry.tokens = tokens
	saveAuthEntry(serverName, entry, serverUrl)
}

/**
 * Update client info for a server.
 */
export function updateClientInfo(serverName: string, clientInfo: StoredClientInfo, serverUrl?: string): void {
	const entry = getAuthEntry(serverName) ?? {}
	entry.clientInfo = clientInfo
	saveAuthEntry(serverName, entry, serverUrl)
}

/**
 * Update code verifier for a server.
 */
export function updateCodeVerifier(serverName: string, codeVerifier: string): void {
	const entry = getAuthEntry(serverName) ?? {}
	entry.codeVerifier = codeVerifier
	saveAuthEntry(serverName, entry)
}

/**
 * Clear code verifier for a server.
 */
export function clearCodeVerifier(serverName: string): void {
	const entry = getAuthEntry(serverName)
	if (entry) {
		delete entry.codeVerifier
		saveAuthEntry(serverName, entry)
	}
}

/**
 * Update OAuth state for a server.
 */
export function updateOAuthState(serverName: string, state: string): void {
	const entry = getAuthEntry(serverName) ?? {}
	entry.oauthState = state
	saveAuthEntry(serverName, entry)
}

/**
 * Get OAuth state for a server.
 */
export function getOAuthState(serverName: string): string | undefined {
	const entry = getAuthEntry(serverName)
	return entry?.oauthState
}

/**
 * Clear OAuth state for a server.
 */
export function clearOAuthState(serverName: string): void {
	const entry = getAuthEntry(serverName)
	if (entry) {
		delete entry.oauthState
		saveAuthEntry(serverName, entry)
	}
}

/**
 * Check if stored tokens are expired.
 * Returns null if no tokens exist, false if no expiry or not expired, true if expired.
 */
export function isTokenExpired(serverName: string): boolean | null {
	const entry = getAuthEntry(serverName)
	if (!entry?.tokens) return null
	if (!entry.tokens.expiresAt) return false
	return entry.tokens.expiresAt < Date.now() / 1000
}

/**
 * Check if a server has stored tokens.
 */
export function hasStoredTokens(serverName: string): boolean {
	const entry = getAuthEntry(serverName)
	return !!entry?.tokens
}

/**
 * Clear all credentials for a server.
 */
export function clearAllCredentials(serverName: string): void {
	removeAuthEntry(serverName)
}

/**
 * Clear only client info for a server.
 */
export function clearClientInfo(serverName: string): void {
	const entry = getAuthEntry(serverName)
	if (entry) {
		delete entry.clientInfo
		saveAuthEntry(serverName, entry)
	}
}

/**
 * Clear only tokens for a server.
 */
export function clearTokens(serverName: string): void {
	const entry = getAuthEntry(serverName)
	if (entry) {
		delete entry.tokens
		saveAuthEntry(serverName, entry)
	}
}

// oauth-handler.ts - OAuth token management for MCP servers
import { existsSync, readFileSync } from "node:fs"
import { join } from "node:path"
import type { OAuthTokens } from "@modelcontextprotocol/sdk/shared/auth.js"
import { getAgentDir } from "./utils.js"

// Token storage path for a server
function getTokensPath(serverName: string): string {
	return join(getAgentDir(), "mcp-oauth", serverName, "tokens.json")
}

/**
 * Get stored OAuth tokens for a server (if any).
 * Returns undefined if no tokens or tokens are expired.
 *
 * Token file location: ~/.pi/agent/mcp-oauth/<server>/tokens.json
 *
 * Expected format:
 * {
 *   "access_token": "...",
 *   "token_type": "bearer",
 *   "refresh_token": "...",  // optional
 *   "expires_in": 3600,      // optional, seconds
 *   "expiresAt": 1234567890  // optional, absolute timestamp ms
 * }
 */
export function getStoredTokens(serverName: string): OAuthTokens | undefined {
	const tokensPath = getTokensPath(serverName)

	if (!existsSync(tokensPath)) return undefined

	try {
		const stored = JSON.parse(readFileSync(tokensPath, "utf-8"))

		// Validate required field
		if (!stored.access_token || typeof stored.access_token !== "string") {
			return undefined
		}

		// Check expiration if expiresAt is set
		if (stored.expiresAt && typeof stored.expiresAt === "number") {
			if (Date.now() > stored.expiresAt) {
				// Token expired
				return undefined
			}
		}

		return {
			access_token: stored.access_token,
			token_type: stored.token_type ?? "bearer",
			refresh_token: stored.refresh_token,
			expires_in: stored.expires_in,
		}
	} catch {
		return undefined
	}
}

/**
 * MCP OAuth Provider
 *
 * Implementation of the MCP SDK's OAuthClientProvider interface.
 * Handles OAuth client registration, token storage, and authorization redirection.
 */

import type { OAuthClientProvider } from "@modelcontextprotocol/sdk/client/auth.js"
import type {
	OAuthClientInformation,
	OAuthClientInformationFull,
	OAuthClientMetadata,
	OAuthTokens,
} from "@modelcontextprotocol/sdk/shared/auth.js"
import {
	type StoredClientInfo,
	type StoredTokens,
	clearAllCredentials,
	clearClientInfo,
	clearTokens,
	getAuthEntry,
	getAuthForUrl,
	updateClientInfo,
	updateCodeVerifier,
	updateOAuthState,
	updateTokens,
} from "./mcp-auth.js"

// Callback server configuration
const DEFAULT_OAUTH_CALLBACK_PORT = 19876
const OAUTH_CALLBACK_PATH = "/mcp/oauth/callback"

let configuredOAuthCallbackPort = DEFAULT_OAUTH_CALLBACK_PORT

if (process.env.MCP_OAUTH_CALLBACK_PORT) {
	const parsedPort = Number.parseInt(process.env.MCP_OAUTH_CALLBACK_PORT, 10)
	if (Number.isInteger(parsedPort) && parsedPort > 0 && parsedPort <= 65535) {
		configuredOAuthCallbackPort = parsedPort
	}
}

let oauthCallbackPort = configuredOAuthCallbackPort

export function getConfiguredOAuthCallbackPort(): number {
	return configuredOAuthCallbackPort
}

export function getOAuthCallbackPort(): number {
	return oauthCallbackPort
}

export function setOAuthCallbackPort(port: number): void {
	oauthCallbackPort = port
}

/** Configuration options for OAuth */
export interface McpOAuthConfig {
	grantType?: "authorization_code" | "client_credentials"
	clientId?: string
	clientSecret?: string
	scope?: string
}

/** Callbacks for OAuth flow interactions */
export interface McpOAuthCallbacks {
	onRedirect: (url: URL) => void | Promise<void>
}

/**
 * OAuth provider implementation for MCP servers.
 * Implements the OAuthClientProvider interface from the MCP SDK.
 */
export class McpOAuthProvider implements OAuthClientProvider {
	constructor(
		private serverName: string,
		private serverUrl: string,
		private config: McpOAuthConfig,
		private callbacks: McpOAuthCallbacks,
	) {}

	private get usesClientCredentials(): boolean {
		return this.config.grantType === "client_credentials"
	}

	/**
	 * The redirect URL for OAuth callbacks.
	 * This must match the redirect_uri in client metadata.
	 */
	get redirectUrl(): string | undefined {
		if (this.usesClientCredentials) return undefined
		return `http://127.0.0.1:${getOAuthCallbackPort()}${OAUTH_CALLBACK_PATH}`
	}

	/**
	 * Client metadata for dynamic registration.
	 * Describes this client to the OAuth authorization server.
	 */
	get clientMetadata(): OAuthClientMetadata {
		if (this.usesClientCredentials) {
			return {
				client_name: "Pi Coding Agent",
				redirect_uris: [],
				grant_types: ["client_credentials"],
				token_endpoint_auth_method: this.config.clientSecret ? "client_secret_post" : "none",
			}
		}

		const redirectUrl = this.redirectUrl
		if (!redirectUrl) {
			throw new Error("redirectUrl is required for authorization_code flow")
		}

		return {
			redirect_uris: [redirectUrl],
			client_name: "Pi Coding Agent",
			client_uri: "https://github.com/nicobailon/pi-mcp-adapter",
			grant_types: ["authorization_code", "refresh_token"],
			response_types: ["code"],
			token_endpoint_auth_method: this.config.clientSecret ? "client_secret_post" : "none",
		}
	}

	/**
	 * Get client information (for pre-registered or dynamically registered clients).
	 * Returns undefined if no client info exists or if the server URL has changed.
	 */
	async clientInformation(): Promise<OAuthClientInformation | undefined> {
		// Check config first (pre-registered client)
		if (this.config.clientId) {
			return {
				client_id: this.config.clientId,
				client_secret: this.config.clientSecret,
			}
		}

		// Check stored client info (from dynamic registration)
		// Use getAuthForUrl to validate credentials are for the current server URL
		const entry = await getAuthForUrl(this.serverName, this.serverUrl)
		if (entry?.clientInfo) {
			// Check if client secret has expired
			if (entry.clientInfo.clientSecretExpiresAt && entry.clientInfo.clientSecretExpiresAt < Date.now() / 1000) {
				return undefined
			}
			return {
				client_id: entry.clientInfo.clientId,
				client_secret: entry.clientInfo.clientSecret,
			}
		}

		// No client info or URL changed - will trigger dynamic registration
		return undefined
	}

	/**
	 * Save client information from dynamic registration.
	 */
	async saveClientInformation(info: OAuthClientInformationFull): Promise<void> {
		const clientInfo: StoredClientInfo = {
			clientId: info.client_id,
			clientSecret: info.client_secret,
			clientIdIssuedAt: info.client_id_issued_at,
			clientSecretExpiresAt: info.client_secret_expires_at,
		}
		updateClientInfo(this.serverName, clientInfo, this.serverUrl)
	}

	/**
	 * Get stored OAuth tokens.
	 * Returns undefined if no tokens exist or if the server URL has changed.
	 */
	async tokens(): Promise<OAuthTokens | undefined> {
		// Use getAuthForUrl to validate tokens are for the current server URL
		const entry = await getAuthForUrl(this.serverName, this.serverUrl)
		if (!entry?.tokens) return undefined

		return {
			access_token: entry.tokens.accessToken,
			token_type: "Bearer",
			refresh_token: entry.tokens.refreshToken,
			expires_in: entry.tokens.expiresAt
				? Math.max(0, Math.floor(entry.tokens.expiresAt - Date.now() / 1000))
				: undefined,
			scope: entry.tokens.scope,
		}
	}

	/**
	 * Save OAuth tokens.
	 */
	async saveTokens(tokens: OAuthTokens): Promise<void> {
		const storedTokens: StoredTokens = {
			accessToken: tokens.access_token,
			refreshToken: tokens.refresh_token,
			expiresAt: tokens.expires_in ? Date.now() / 1000 + tokens.expires_in : undefined,
			scope: tokens.scope,
		}
		updateTokens(this.serverName, storedTokens, this.serverUrl)
	}

	/**
	 * Redirect the user to the authorization URL.
	 * This opens the browser for the user to authenticate.
	 */
	async redirectToAuthorization(authorizationUrl: URL): Promise<void> {
		if (this.usesClientCredentials) {
			throw new Error("redirectToAuthorization is not used for client_credentials flow")
		}
		// URL is passed to callback, not logged (may contain sensitive params)
		await this.callbacks.onRedirect(authorizationUrl)
	}

	/**
	 * Save the PKCE code verifier.
	 */
	async saveCodeVerifier(codeVerifier: string): Promise<void> {
		updateCodeVerifier(this.serverName, codeVerifier)
	}

	/**
	 * Get the stored PKCE code verifier.
	 * @throws Error if no code verifier is stored
	 */
	async codeVerifier(): Promise<string> {
		if (this.usesClientCredentials) {
			throw new Error("codeVerifier is not used for client_credentials flow")
		}
		const entry = await getAuthEntry(this.serverName)
		if (!entry?.codeVerifier) {
			throw new Error(`No code verifier saved for MCP server: ${this.serverName}`)
		}
		return entry.codeVerifier
	}

	/**
	 * Save the OAuth state parameter for CSRF protection.
	 */
	async saveState(state: string): Promise<void> {
		updateOAuthState(this.serverName, state)
	}

	/**
	 * Get the stored OAuth state parameter.
	 * @throws Error if no state is stored
	 */
	async state(): Promise<string> {
		if (this.usesClientCredentials) {
			throw new Error("state is not used for client_credentials flow")
		}
		const entry = await getAuthEntry(this.serverName)
		if (!entry?.oauthState) {
			throw new Error(`No OAuth state saved for MCP server: ${this.serverName}`)
		}
		return entry.oauthState
	}

	/**
	 * Invalidate credentials when authentication fails.
	 * Clears tokens, client info, or all credentials based on the type.
	 */
	async invalidateCredentials(type: "all" | "client" | "tokens"): Promise<void> {
		switch (type) {
			case "all":
				clearAllCredentials(this.serverName)
				break
			case "client":
				clearClientInfo(this.serverName)
				break
			case "tokens":
				clearTokens(this.serverName)
				break
		}
	}

	prepareTokenRequest(scope?: string): URLSearchParams | undefined {
		if (!this.usesClientCredentials) {
			return undefined
		}

		const params = new URLSearchParams({ grant_type: "client_credentials" })
		const requestedScope = scope ?? this.config.scope
		if (requestedScope) {
			params.set("scope", requestedScope)
		}
		return params
	}
}

export { DEFAULT_OAUTH_CALLBACK_PORT, OAUTH_CALLBACK_PATH }

import { RemoteNetworkError } from "../types.js"
import { verifyApiKey } from "./keys.js"
import { createOrUpdateSession, exchangeSessionToken } from "./sessions.js"
import type { AuthenticateOptions, AuthenticateResponse } from "./types.js"
import { RemoteAuthError } from "./types.js"
import { normalizeWsUri } from "./uri.js"

/**
 * Three-step authentication flow:
 * 1. Verify API key → organizationId.
 * 2. Create or update session → get WebSocket URI.
 * 3. Exchange for session token → get JWT for WebSocket auth.
 *
 * Keeps the same {@link AuthenticateResponse} shape so reconnect.ts and
 * transport-ws.ts do not need to change.
 */
export async function authenticateRemoteSession(
	sessionId: string,
	apiKey: string,
	description: string,
	options?: AuthenticateOptions,
): Promise<AuthenticateResponse> {
	const fetchImpl = options?.fetch ?? globalThis.fetch

	try {
		const orgId = await verifyApiKey(apiKey, { ...options, fetch: fetchImpl })
		const session = await createOrUpdateSession(orgId, sessionId, apiKey, description, {
			...options,
			fetch: fetchImpl,
		})
		const { token, expireTime } = await exchangeSessionToken(apiKey, sessionId, { ...options, fetch: fetchImpl })

		const { wsUrl, host } = normalizeWsUri(session.uri)

		return {
			connectToken: token,
			expiresAt: expireTime,
			wsUrl,
			host,
			description: session.description,
		}
	} catch (err) {
		if (err instanceof RemoteAuthError || err instanceof RemoteNetworkError) {
			throw err
		}
		throw new RemoteNetworkError(err instanceof Error ? err.message : String(err))
	}
}

