import { TEST_MODELS } from "../../integrations/__fixtures__/models.js"
import "../../integrations/claude-code.js"
import "../../integrations/cursor.js"
import { byId } from "../../integrations/registry.js"
import * as modelsModule from "../../models.js"
import type { WizardState } from "../state.js"
import { runDoneStep } from "./done.js"

const installRtkMock = vi.hoisted(() => vi.fn())

vi.mock("../../resources/rtk-install.js", () => ({
	installRtk: installRtkMock,
}))

describe("runDoneStep", () => {
	let tmpHome: string
	let prevHome: string | undefined
	let prevShell: string | undefined

	beforeEach(() => {
		// runDoneStep calls exportEnvToShellProfile, which writes to $HOME's
		// shell profile. Redirect HOME to a scratch dir so we don't append
		// to the test runner's real .zshrc / .bashrc.
		tmpHome = realpathSync(mkdtempSync(join(tmpdir(), "done-step-test-")))
		prevHome = process.env.HOME
		prevShell = process.env.SHELL
		process.env.HOME = tmpHome
		// Pin shell so detection is deterministic across CI environments.
		process.env.SHELL = "/bin/zsh"

		// @clack/prompts writes its UI to stdout; silence it so the test
		// runner output stays focused on assertions.
		vi.spyOn(process.stdout, "write").mockImplementation(() => true)
		vi.spyOn(console, "warn").mockImplementation(() => {})

		// Mock updateModelsConfig so we don't hit the real network.
		vi.spyOn(modelsModule, "updateModelsConfig").mockResolvedValue({
			models: TEST_MODELS as import("../../models.js").ModelMetadata[],
		})
		installRtkMock.mockReset()
		installRtkMock.mockResolvedValue({
			version: "v1.2.3",
			binaryPath: "/tmp/kimchi-test/rtk",
			linkPath: "/tmp/kimchi-test/bin/rtk",
		})

		clackMock.spinnerInstance.start.mockClear()
		clackMock.spinnerInstance.stop.mockClear()
		clackMock.spinnerInstance.message.mockClear()
		clackMock.spinner.mockClear()
		clackMock.log.info.mockClear()
		clackMock.log.error.mockClear()
		clackMock.log.warn.mockClear()
		clackMock.note.mockClear()
		clackMock.outro.mockClear()
	})

	afterEach(() => {
		// biome-ignore lint/performance/noDelete: env-var cleanup needs a real delete; assigning undefined would coerce to the literal string "undefined".
		if (prevHome === undefined) delete process.env.HOME
		else process.env.HOME = prevHome
		// biome-ignore lint/performance/noDelete: same reason as HOME above.
		if (prevShell === undefined) delete process.env.SHELL
		else process.env.SHELL = prevShell
		rmSync(tmpHome, { recursive: true, force: true })
		vi.restoreAllMocks()
	})

	function baseState(): WizardState {
		return {
			apiKey: "test-key",
			mode: "override",
			scope: "global",
			selectedTools: ["claudecode"],
			telemetryEnabled: true,
			cancelled: false,
			back: false,
		}
	}

	function getClaudeCodeTool() {
		const tool = byId("claudecode")
		if (!tool) throw new Error("claudecode integration not registered — wiring bug")
		return tool
	}

	it("override mode invokes the integration writer with models from the API", async () => {
		const tool = getClaudeCodeTool()
		const writeSpy = vi.spyOn(tool, "write").mockResolvedValue()

		const outcome = await runDoneStep(baseState())
		// write is called with (scope, apiKey, models, options)
		expect(writeSpy).toHaveBeenCalledWith("global", "test-key", TEST_MODELS, { telemetryEnabled: true })
		expect(outcome.successes).toEqual(["Claude Code"])
		expect(outcome.failures).toEqual([])

		writeSpy.mockRestore()
	})

	it("aborts before configuring tools when model fetch fails without a cache", async () => {
		vi.mocked(modelsModule.updateModelsConfig).mockRejectedValueOnce(
			new Error("self signed certificate in certificate chain"),
		)
		const tool = getClaudeCodeTool()
		const writeSpy = vi.spyOn(tool, "write").mockResolvedValue()

		const outcome = await runDoneStep(baseState())

		expect(writeSpy).not.toHaveBeenCalled()
		expect(outcome.successes).toEqual([])
		expect(outcome.failures).toEqual([
			{ id: "*", error: "model fetch failed: self signed certificate in certificate chain" },
		])
		expect(clackMock.spinnerInstance.stop).toHaveBeenCalledWith(
			"Could not fetch available models: self signed certificate in certificate chain",
		)
		expect(clackMock.outro).toHaveBeenCalledWith("Aborted.")

		writeSpy.mockRestore()
	})

	it("inject mode skips the writer entirely", async () => {
		const tool = getClaudeCodeTool()
		const writeSpy = vi.spyOn(tool, "write").mockResolvedValue()

		const state = baseState()
		state.mode = "inject"
		const outcome = await runDoneStep(state)

		expect(writeSpy).not.toHaveBeenCalled()
		// Tool still listed as a "success" so the user knows it's wired —
		// just via the launcher rather than a config file.
		expect(outcome.successes).toEqual(["Claude Code"])
		expect(outcome.failures).toEqual([])

		writeSpy.mockRestore()
	})

	it("ensures RTK when setup requests it", async () => {
		const tool = getClaudeCodeTool()
		const writeSpy = vi.spyOn(tool, "write").mockResolvedValue()
		const state = baseState()
		state.installRtk = true

		const outcome = await runDoneStep(state)

		expect(installRtkMock).toHaveBeenCalledTimes(1)
		expect(outcome.rtkInstalled).toBe(true)
		expect(outcome.failures).toEqual([])

		writeSpy.mockRestore()
	})

	it("treats RTK install failure as a setup warning", async () => {
		const tool = getClaudeCodeTool()
		const writeSpy = vi.spyOn(tool, "write").mockResolvedValue()
		installRtkMock.mockRejectedValueOnce(new Error("GitHub rate limited"))
		const state = baseState()
		state.installRtk = true

		const outcome = await runDoneStep(state)

		expect(outcome.successes).toEqual(["Claude Code"])
		expect(outcome.failures).toEqual([])
		expect(outcome.warnings).toEqual([{ id: "rtk", error: "GitHub rate limited" }])

		writeSpy.mockRestore()
	})

	it("collects failures rather than aborting on a single broken writer", async () => {
		const tool = getClaudeCodeTool()
		const writeSpy = vi.spyOn(tool, "write").mockRejectedValue(new Error("disk full"))

		const outcome = await runDoneStep(baseState())
		expect(outcome.successes).toEqual([])
		expect(outcome.failures).toEqual([{ id: "claudecode", error: "disk full" }])

		writeSpy.mockRestore()
	})

	it("returns failures for unregistered tool ids without throwing", async () => {
		const state = baseState()
		// Cast through unknown to bypass the ToolId compile check — production
		// callers only ever pass valid ids, but defensive code in the step
		// shouldn't blow up if a future caller misuses this entry point.
		state.selectedTools = ["never-registered" as unknown as "claudecode"]
		const outcome = await runDoneStep(state)
		expect(outcome.successes).toEqual([])
		expect(outcome.failures[0]?.id).toBe("never-registered")
	})

	it("exports KIMCHI_API_KEY to the user's shell profile", async () => {
		const tool = getClaudeCodeTool()
		const writeSpy = vi.spyOn(tool, "write").mockResolvedValue()

		await runDoneStep(baseState())
		const { readFileSync } = await import("node:fs")
		const zshrc = readFileSync(join(tmpHome, ".zshrc"), "utf-8")
		expect(zshrc).toContain("export KIMCHI_API_KEY=test-key")

		writeSpy.mockRestore()
	})

	it("skips the spinner for interactive-write tools", async () => {
		const tool = getClaudeCodeTool()
		const writeSpy = vi.spyOn(tool, "write").mockResolvedValue()

		await runDoneStep(baseState())
		const toolSpinnerStarts = clackMock.spinnerInstance.start.mock.calls.filter(
			(call: unknown[]) => typeof call[0] === "string" && call[0].includes("Claude Code"),
		)
		expect(toolSpinnerStarts).toEqual([])
		expect(clackMock.log.info).toHaveBeenCalledWith("Configuring Claude Code…")
		expect(clackMock.log.info).toHaveBeenCalledWith("Claude Code: configured")

		writeSpy.mockRestore()
	})

	it("uses the spinner for non-interactive tools", async () => {
		const state = baseState()
		state.selectedTools = ["cursor"]

		const tool = byId("cursor")
		if (!tool) throw new Error("cursor integration not registered")
		const writeSpy = vi.spyOn(tool, "write").mockResolvedValue()

		await runDoneStep(state)
		const toolSpinnerStarts = clackMock.spinnerInstance.start.mock.calls.filter(
			(call: unknown[]) => typeof call[0] === "string" && call[0].includes("Cursor"),
		)
		expect(toolSpinnerStarts).toEqual([["Configuring Cursor…"]])

		writeSpy.mockRestore()
	})
})

import { describe, expect, it, vi } from "vitest"
import { validateApiKey } from "./validator.js"

function fakeFetch(response: { status: number } | Error): typeof globalThis.fetch {
	return vi.fn(async () => {
		if (response instanceof Error) throw response
		return new Response(null, { status: response.status })
	}) as unknown as typeof globalThis.fetch
}

describe("validateApiKey", () => {
	it("rejects an empty key without making a request", async () => {
		const fetchSpy = vi.fn() as unknown as typeof globalThis.fetch
		const result = await validateApiKey("", { fetch: fetchSpy })
		expect(result.valid).toBe(false)
		expect(result.error).toMatch(/required/)
		expect(fetchSpy).not.toHaveBeenCalled()
	})

	it("returns valid:true on HTTP 200", async () => {
		const result = await validateApiKey("k", { fetch: fakeFetch({ status: 200 }) })
		expect(result).toEqual({ valid: true })
	})

	it("returns Invalid API key on 401 with actionable suggestions", async () => {
		const result = await validateApiKey("bad", { fetch: fakeFetch({ status: 401 }) })
		expect(result.valid).toBe(false)
		expect(result.error).toMatch(/Invalid/)
		expect(result.suggestions).toEqual(expect.arrayContaining([expect.stringMatching(/app\.kimchi\.dev/)]))
	})

	it("returns scope error on 403", async () => {
		const result = await validateApiKey("k", { fetch: fakeFetch({ status: 403 }) })
		expect(result.valid).toBe(false)
		expect(result.error).toMatch(/permissions/)
	})

	it("treats non-2xx/4xx as transient", async () => {
		const result = await validateApiKey("k", { fetch: fakeFetch({ status: 502 }) })
		expect(result.valid).toBe(false)
		expect(result.error).toMatch(/status 502/)
	})

	it("converts network failures to a friendly Network error result", async () => {
		const result = await validateApiKey("k", { fetch: fakeFetch(new Error("ENOTFOUND")) })
		expect(result.valid).toBe(false)
		expect(result.error).toMatch(/Network error/)
	})

	it("aborts the request after the configured timeout", async () => {
		const slow: typeof globalThis.fetch = (_url, init) =>
			new Promise((_resolve, reject) => {
				const signal = init?.signal as AbortSignal | undefined
				signal?.addEventListener("abort", () => reject(new Error("aborted")))
			})
		const result = await validateApiKey("k", { fetch: slow, timeoutMs: 5 })
		expect(result.valid).toBe(false)
		expect(result.error).toMatch(/Network error/)
	})

	it("forwards Authorization: Bearer header to the validation endpoint", async () => {
		const fetchSpy = vi.fn(async () => new Response(null, { status: 200 }))
		await validateApiKey("my-key", { fetch: fetchSpy as unknown as typeof globalThis.fetch })
		expect(fetchSpy).toHaveBeenCalledWith(
			"https://api.cast.ai/v1/llm/openai/supported-providers",
			expect.objectContaining({
				headers: expect.objectContaining({ Authorization: "Bearer my-key" }),
			}),
		)
	})
})

import { describe, expect, it } from "vitest"
import { parseClassifierOutput } from "./classifier.js"

describe("parseClassifierOutput", () => {
	it("parses a valid safe verdict", () => {
		const r = parseClassifierOutput(`{ "verdict": "safe", "reason": "project build" }`)
		expect(r.verdict).toBe("safe")
		expect(r.reason).toBe("project build")
		expect(r.ok).toBe(true)
	})

	it("parses requires-confirmation", () => {
		const r = parseClassifierOutput(`{"verdict":"requires-confirmation","reason":"ambiguous"}`)
		expect(r.verdict).toBe("requires-confirmation")
	})

	it("parses blocked", () => {
		const r = parseClassifierOutput(`{"verdict":"blocked","reason":"destructive"}`)
		expect(r.verdict).toBe("blocked")
	})

	it("extracts embedded JSON when LLM adds prose", () => {
		const raw = `Sure. Here is my answer:\n\n{"verdict":"safe","reason":"fine"}\n\nHope that helps.`
		expect(parseClassifierOutput(raw).verdict).toBe("safe")
	})

	it("falls back to requires-confirmation on garbage", () => {
		const r = parseClassifierOutput("not json at all")
		expect(r.verdict).toBe("requires-confirmation")
		expect(r.reason).toContain("unparseable")
		expect(r.ok).toBe(false)
	})

	it("falls back on unknown verdict", () => {
		const r = parseClassifierOutput(`{"verdict":"maybe","reason":"x"}`)
		expect(r.verdict).toBe("requires-confirmation")
		expect(r.ok).toBe(false)
	})

	it("defaults reason when missing", () => {
		const r = parseClassifierOutput(`{"verdict":"safe"}`)
		expect(r.reason).toBe("no reason provided")
	})
})
